def check_with_scope(actor_card_id: str, target_card_id: str,
                     action: Perm, card_store) -> bool:
    if not check(target_card_id, action, card_store):
        return False
    if action in (Perm.EDIT, Perm.DELETE, Perm.LINK, Perm.UNLINK, Perm.CREATE_CHILD):
        target = card_store.get_card(target_card_id)
        granted = POLICY.get(target.get("card_type", ""), DEFAULT_POLICY)
        if Perm.TREE_SCOPE in granted:
            if not _is_in_subtree(actor_card_id, target_card_id, card_store):
                return False
    return True

def _is_in_subtree(root_id: str, target_id: str, card_store) -> bool:
    current = target_id
    while current:
        if current == root_id:
            return True
        node = card_store.get_card(current)
        current = node.get("parent_id") if node else None
    return False
