def build_tools_for_card(card_id: str, card_store, all_tools: dict) -> list:
    card = card_store.get_card(card_id)
    granted = POLICY.get(card.get("card_type", ""), DEFAULT_POLICY)
    tool_group_map = {
        Perm.TOOL_SEARCH: ["search_cards", "search_files"],
        Perm.TOOL_FILE:   ["read_file", "write_file", "list_dir"],
        Perm.TOOL_WEB:    ["web_search", "web_fetch"],
        Perm.TOOL_CARD:   ["create_card", "update_card", "link_cards"],
    }
    visible = []
    for perm_flag, names in tool_group_map.items():
        if perm_flag in granted:
            visible += [all_tools[n] for n in names if n in all_tools]
    return visible
```

