def check_file_access(card_id: str, filepath: str, card_store) -> bool:
    card = card_store.get_card(card_id)
    ctype = card.get("card_type", "")
    if Perm.TOOL_FILE not in POLICY.get(ctype, DEFAULT_POLICY):
        return False
    return any(filepath.startswith(p) for p in FILE_SCOPE.get(ctype, []))
